                </div>
                <div style={{ flex: 1, overflow: 'hidden', padding: '10px 14px', minHeight: 0 }}>
                  <WidgetContent widget={widget} />
                </div>
              </Card>
            </div>
          );
        })}
      </GridLayout>
    </div>
  );
}
